/**
 * utils/openPopup.js - open external URLs in a centered popup or a plain tab.
 *
 * The single allowed path for opening user-supplied or database URLs, centralised so the
 * protocol allowlist can never be forgotten at a call site. Two exits, and the choice matters:
 * `openPopup` is a chrome-less window, right for a single glance at a phone-shaped destination;
 * `openTab` is an ordinary tab, right for anything the user will navigate inside, because a
 * popup has NO BACK BUTTON and cannot spawn real tabs.
 *
 * @param {string} url - destination; rejected unless http(s)
 * @param {number} [width=480] - requested px; the 480x720 default suits phone-shaped
 *        destinations. Pass a desktop size for anything that renders a desktop layout.
 * @security Only http/https are opened. javascript:, data: and other schemes are blocked, to
 *           prevent script injection through a stored URL field.
 * @gotcha the requested size is clamped to the available screen, so a caller asking for a
 *         window wider than the display still lands on-screen.
 */
export function openPopup(url, width = 480, height = 720) {
  if (!url) return;
  try {
    const parsed = new URL(url);
    if (!['http:', 'https:'].includes(parsed.protocol)) return;
  } catch {
    return;
  }
  width  = Math.min(width,  window.screen?.availWidth  || width);
  height = Math.min(height, window.screen?.availHeight || height);
  const left = Math.round(window.screenX + (window.outerWidth  - width)  / 2);
  const top  = Math.round(window.screenY + (window.outerHeight - height) / 2);
  window.open(url, '_blank',
    `width=${width},height=${height},left=${left},top=${top},` +
    `toolbar=0,menubar=0,location=0,status=0,scrollbars=1,resizable=1,noopener`);
}

/**
 * Claim a popup NOW, for a URL that has not arrived yet.
 *
 * A browser grants `window.open` on the strength of the click that is running. Six callers
 * minted a signed storage URL first and opened the popup after the await, which is a different
 * task, so Safari in particular refuses it and the person presses View and nothing happens.
 * This opens the empty window inside the click and points it at the URL when it lands.
 *
 * @security `opener` is severed on the reserved window. `noopener` cannot be passed to a
 *           window whose location is assigned later, so it is done by hand instead, and the
 *           protocol allowlist still runs in `show`.
 * @gotcha `show(null)` CLOSES the reserved window. A read that failed must not leave a blank
 *         popup sitting over the page.
 * @returns {{show: function, cancel: function}}
 * @see .claude/rules/agency-dashboard.md, docs/CODEBASE.md
 */
export function reservePopup(width = 480, height = 720) {
  const w = window.open('', '_blank',
    `width=${width},height=${height},toolbar=0,menubar=0,location=0,status=0,scrollbars=1,resizable=1`);
  if (w) w.opener = null;
  return {
    show(url) {
      if (!w) { openPopup(url, width, height); return; }   // blocked outright: try the plain way
      if (!url) { w.close(); return; }
      try {
        const parsed = new URL(url);
        if (!['http:', 'https:'].includes(parsed.protocol)) { w.close(); return; }
      } catch { w.close(); return; }
      w.location = url;
    },
    cancel() { if (w) w.close(); },
  };
}

/**
 * Open a URL in an ordinary browser tab, with full browser chrome.
 *
 * @param {string} url - destination; rejected unless http(s)
 * @security Same http(s) allowlist as openPopup, plus noopener so the opened
 *           page cannot reach back through window.opener.
 * @gotcha Use this, not openPopup, for any destination the user will navigate
 *         within. A chrome-less popup has no back button, so following a link
 *         inside one is a dead end, and a window.open from inside it yields
 *         another popup rather than a tab (the agency dashboard preview and its
 *         invoice links.
 */
export function openTab(url) {
  if (!url) return;
  try {
    const parsed = new URL(url);
    if (!['http:', 'https:'].includes(parsed.protocol)) return;
  } catch {
    return;
  }
  window.open(url, '_blank', 'noopener');
}
