/**
 * utils/statusRow.js: the one home for turning a status id or value into its `status_options`
 * row, and therefore the one home for what a status pill draws.
 *
 * It owns the RESOLUTION ORDER and nothing else. Presentation stays at the call site: only two
 * of the eight pills draw a `.badge` and the rest are bespoke spans with their own radii, sizes
 * and colour channels, so a component here would have to own five shapes.
 *
 * Used by: components/shared/Badge.js, StatusBadges.js, CalendarPage.js, RewardsPage.js,
 * components/creator/MobilePostPage.js.
 *
 * @gotcha the GROUP is required and is the point. 'Pending' exists in three groups, so a value
 *         searched across all of them resolves to whichever `group_key` sorts first, which is
 *         not a decision anybody made. @see .claude/rules/hub-modules.md
 * @gotcha no `error` or `loading` branch. `StatusVocabularyGate` (App.js) stops a refused
 *         `status_options` read before any pill renders; a group still loading is the call
 *         site's own question, since some of them draw a placeholder.
 * @invariant one no-match answer: `null`. A caller that wants a fallback states it itself.
 * @see .claude/rules/hub-data.md (status vocabulary is data)
 */
import { STATUS_VOCABULARY } from './statusValues';

/** The five legal `status_options.group_key` values, read from their one home. */
export const STATUS_GROUPS = Object.keys(STATUS_VOCABULARY);

/**
 * The unfiltered choice a status filter list opens with, shaped like a `status_options` row so
 * a chip list is one array and one render.
 *
 * It lives here rather than in each page because the shape is the point: six render sites used
 * to spread `['all', ...group.map(s => s.value)]` and then write `s === 'all' ? 'All' : s`,
 * which made the raw VALUE the default text beside badges printing `label`. A list of rows has
 * no such default.
 */
export const ALL_CHOICE = { value: 'all', label: 'All' };

/**
 * The `status_options` row a pill should draw, or null.
 *
 * @param {object} options - `useStatusOptions().options`, keyed by `group_key`.
 * @param {string} group - one of STATUS_GROUPS. A group this vocabulary does not have is a
 *        programming error, not a miss, so it throws in development rather than resolving.
 * @param {object} keys
 * @param {string} [keys.statusId] - the row id. When present it is the ONLY key used, never
 *        falling back to a `status` string that may name a different, live row.
 * @param {string} [keys.status] - the row value, used only when no id is given.
 * @returns {object|null}
 */
export function resolveStatusRow(options, group, { statusId, status } = {}) {
  if (process.env.NODE_ENV !== 'production' && !STATUS_GROUPS.includes(group)) {
    throw new Error(`resolveStatusRow: "${group}" is not a status_options group. One of: ${STATUS_GROUPS.join(', ')}`);
  }
  const rows = (options && options[group]) || [];
  if (statusId) return rows.find(r => r.id === statusId) || null;
  if (status) return rows.find(r => r.value === status) || null;
  return null;
}
