/**
 * components/shared/Loading.js: the one home for "this screen is fetching".
 *
 * Thirty-one screens rendered the same muted `Loading…` div and the hub held four
 * `aria-live` attributes in total, so a screen reader user who filtered a table or reloaded the
 * ledger heard nothing at all until they went looking. The markup was already identical
 * everywhere; what it was missing was the one attribute that makes it audible.
 *
 * @gotcha `role="status"` carries an IMPLICIT `aria-live="polite"`, and the explicit attribute
 *         is here anyway because two engines only honour the explicit one. Polite, never
 *         assertive: a fetch is not an interruption.
 * @gotcha this is the LOADING state, not the error state and not the empty state. Those go
 *         through `Feedback` and through the screen's own copy. @see .claude/rules/hub-ui.md
 * @see hub-src/src/__tests__/loadingAndErrorAnnouncements.test.js
 */
import React from 'react';

/**
 * @param {React.ReactNode} [props.children='Loading…'] what is being fetched, said in words
 * @param {string} [props.className='text-muted'] the caller's own styling, unchanged
 * @param {object} [props.style]
 */
export default function Loading({ children = 'Loading…', className = 'text-muted', style }) {
  return (
    <div className={className} style={style} role="status" aria-live="polite">
      {children}
    </div>
  );
}
