/**
 * utils/markPosted.js - the one way a deliverable becomes Posted.
 *
 * Writes `post_url`, `actual_post_date`, `draft_status_id`, `posted_by` and `posted_at`, then
 * reads the row back.
 *
 * @invariant a caller gets either `error: null` AND a row that provably holds what it sent, or
 *            an error. There is no third outcome. The read-back is not padding:
 *            `restrict_creator_deliverable_columns` silently REVERTS a creator write it does
 *            not permit rather than raising, so a refused save returns success with zero rows
 *            changed and is otherwise indistinguishable from a real one.
 * @gotcha the read-back compares ONLY `post_url` and `draft_status_id`. Never widen it to a
 *         column the database may rewrite: the status trigger coerces a null and the display
 *         name trigger writes a DIFFERENT table, so either would read a correct save as failed.
 * @see utils/mutate.js
 */
import { mutate } from './mutate';

/**
 * Flip one deliverable to Posted, and prove it landed.
 *
 * @param {object} args
 * @param {object} args.supabase      the client, injected so this module stays a leaf
 * @param {string} args.deliverableId the row to update
 * @param {string} args.postedStatusId the `status_options` id whose value is 'Posted'
 * @param {?string} args.postUrl      the live post, or null
 * @param {?string} args.postDate     `actual_post_date`, or null
 * @param {?string} args.userId       stamped into `posted_by`
 * @param {object} [args.extra]       extra columns to write in the SAME statement,
 *        for the caller that also records a music brief. Merged before the write so
 *        a sound and a status can never land as two half-applied updates.
 * @returns {Promise<{error: ?{tone: string, title: string, body: ?string}}>}
 *          `error` is null on success and is already a `humanizeError` feedback
 *          object otherwise, so `if (error)` is the whole check and nothing
 *          downstream may humanize it a second time.
 */
export async function markPosted({
  supabase,
  deliverableId,
  postedStatusId,
  postUrl,
  postDate,
  userId,
  extra = {},
}) {
  // A null status id is the incident in miniature: the write would set
  // draft_status_id null, the default trigger would coerce it to 'Not Started', and
  // the row would read as saved while never becoming Posted. Refuse instead, because
  // the only way to reach this is StatusOptions not having loaded.
  if (!postedStatusId) {
    return {
      error: {
        tone: 'error',
        title: "Couldn't mark this posted",
        body: 'The status list has not loaded yet. Refresh and try again.',
      },
    };
  }

  const url = postUrl || null;
  const update = {
    ...extra,
    post_url: url,
    actual_post_date: postDate || null,
    draft_status_id: postedStatusId,
    posted_by: userId || null,
    posted_at: new Date().toISOString(),
  };

  const { data, error } = await mutate(
    supabase
      .from('campaign_deliverables')
      .update(update)
      .eq('id', deliverableId)
      .select('id, post_url, draft_status_id'),
  );
  if (error) return { error };

  const row = (data || [])[0];
  if (!row || row.post_url !== url || row.draft_status_id !== postedStatusId) {
    return {
      error: {
        tone: 'error',
        title: "Couldn't mark this posted",
        body: 'The save returned without applying your changes. Refresh and try again, or ask Patrick to check.',
      },
    };
  }
  return { error: null };
}

/**
 * What is still standing between this deliverable and Posted, as a list she can read.
 *
 * The button's `disabled` is derived from the LENGTH of this list, so the list and the
 * gate cannot drift: a condition that greys the button is a condition that names itself.
 *
 * @param {object} args
 * @param {?object} args.deliverable   the row on screen, or null when none is open
 * @param {?string} args.postUrl       the picked video's URL
 * @param {boolean} args.musicAnswered `canSubmitMusic` at the call site: a valid sound link,
 *        or the explicit "they didn't send one" on an optional type
 * @param {boolean} args.ftcChecked
 * @param {object} args.hashtagChecks  `{ [tag]: boolean }`
 * @returns {Array<{key: string, label: string}>} in the order the controls appear on the
 *          screen, so the first outstanding item is also the highest one to scroll back to.
 * @gotcha the video is FIRST deliberately. Its picker sits at the top of a phone screen and
 *         has scrolled out of sight by the time the hashtag list renders, so it is the one
 *         condition a reader cannot guess from what is in front of her.
 */
export function outstandingPostRequirements({
  deliverable,
  postUrl,
  musicAnswered,
  ftcChecked,
  hashtagChecks,
}) {
  if (!deliverable) return [];
  const out = [];
  if (!postUrl) out.push({ key: 'video', label: 'Select the video you posted' });
  if (deliverable.platform?.name?.toLowerCase() === 'tiktok' && !musicAnswered) {
    out.push({ key: 'music', label: 'Answer the contracted sound' });
  }
  if (deliverable.ftc_disclosure === 'required' && !ftcChecked) {
    out.push({ key: 'ftc', label: 'Confirm the FTC disclosure' });
  }
  for (const tag of deliverable.required_hashtags || []) {
    if (!(hashtagChecks || {})[tag]) {
      out.push({ key: `hashtag:${tag}`, label: `Confirm you used #${tag}` });
    }
  }
  return out;
}
