/**
 * hooks/useLoadState.js - the two flags a loader raises, and which one it raises when.
 *
 * `loading` was doing two jobs. The first load has nothing on screen, so a spinner is the
 * honest answer. A refetch after a save has the whole table, the totals and often an open
 * detail panel already on screen, and raising the same flag threw all of it away and put a
 * spinner in its place. The discriminator is whether a load has ever finished, which is the
 * only thing this hook holds beyond the two booleans.
 *
 * Used by: PaymentsPage, ExpensesPage, CampaignsPage, and any list surface whose loader is
 * re-invoked after a write.
 *
 * @invariant every path out of a load calls `end()`. A `return` that skips it leaves the
 *            page reading as though a fetch were still running, forever.
 * @gotcha a load that FAILED still counts as completed. The retry on `ReadError` re-invokes
 *         the same loader, and raising `loading` there discards the reason the read failed
 *         along with the Try again control the reader just pressed.
 * @see components/shared/Refreshing.js, .claude/rules/hub-ui.md (the four data states)
 */
import { useCallback, useRef, useState } from 'react';

/**
 * @returns {{loading: boolean, refreshing: boolean, begin: function, end: function}}
 *          `loading` for the first load only, `refreshing` for every one after it.
 */
export function useLoadState() {
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  // A ref, not state: `begin` is called from inside a loader that closed over an earlier
  // render, and a stale `loading` there would blank the page on the second save.
  const settled = useRef(false);

  const begin = useCallback(() => {
    if (settled.current) setRefreshing(true);
    else setLoading(true);
  }, []);

  const end = useCallback(() => {
    settled.current = true;
    setLoading(false);
    setRefreshing(false);
  }, []);

  return { loading, refreshing, begin, end };
}
