/**
 * components/shared/Refreshing.js - "this list is being re-read", without taking the list away.
 *
 * The fourth data state has a sibling nobody had written down: a screen that already has an
 * answer and is checking it again. It is not Loading, because there is something on screen and
 * a spinner would destroy it; it is not Data, because the figures are a second old. It rides
 * inline on the page subtitle so it costs no row and moves nothing.
 *
 * Deliberately still and deliberately grey. Orange is the one moment of heat in this product
 * and a background re-read does not earn it, and a pulsing word would be decoration that then
 * needs its own reduced-motion rule. @see .impeccable.md (principles 1, 2 and 4)
 *
 * @gotcha `role="status"` is not optional. A visual-only indicator is a blank screen to a
 *         screen reader, which is the defect `loadingAndErrorAnnouncements.test.js` exists to
 *         stop. It is rendered only while true so the polite announcement fires on the change.
 * @see hooks/useLoadState.js, .claude/rules/hub-ui.md
 */
import React from 'react';

/** @param {boolean} props.on - whether a refetch is in flight. */
export default function Refreshing({ on }) {
  if (!on) return null;
  return (
    <span
      role="status"
      aria-live="polite"
      style={{ marginLeft: 10, fontSize: 11, letterSpacing: 1, textTransform: 'uppercase', color: 'var(--dim)' }}
    >
      Refreshing
    </span>
  );
}
