/**
 * components/shared/SubmitButton.js: the one home for a button that is mid-save.
 *
 * Thirty-nine buttons wrote `{saving ? 'Saving…' : 'Save'}` and `disabled={saving}` by hand.
 * The screen said the save was running and the software said nothing: a DISABLED control's
 * label change is announced by no engine, so between the click and the outcome a screen reader
 * user could not tell a save that was running from a click that never landed.
 *
 * @gotcha the announcement lives in a SIBLING status region, not on the button. `aria-live` on
 *         the button itself announces the flip back to "Save" as well, and that half is noise;
 *         a region that empties announces nothing.
 * @gotcha `polite`, and polite regions queue, so a fast save reads "Saving…" and then the
 *         success toast rather than the two colliding.
 * @gotcha the region is `.sr-only`, which is `position: absolute`. That is load bearing: an
 *         in-flow sibling becomes a flex item of `.modal-footer` and takes a `gap` beside the
 *         button it belongs to.
 * @gotcha `disabled` is the CALLER's own reason (an incomplete form) OR the save being in
 *         flight, never one replacing the other.
 * @see hub-src/src/__tests__/submitInFlight.test.js
 */
import React from 'react';

/**
 * @param {boolean} props.saving         whether the save is in flight
 * @param {string} [props.savingLabel='Saving…'] what to say while it is
 * @param {string} [props.className='btn btn-primary']
 * @param {boolean} [props.disabled]     the caller's own reason to refuse the click
 * @param {React.ReactNode} props.children the resting label
 */
export default function SubmitButton({
  saving,
  savingLabel = 'Saving…',
  className = 'btn btn-primary',
  disabled = false,
  children,
  ...rest
}) {
  return (
    <>
      <button
        className={className}
        disabled={disabled || saving}
        aria-busy={saving || undefined}
        {...rest}
      >
        {saving ? savingLabel : children}
      </button>
      <span className="sr-only" role="status">{saving ? savingLabel : ''}</span>
    </>
  );
}
