/**
 * components/shared/EmptyState.js: the one home for the `.empty-state` family.
 *
 * The third of the four states (Loading, Error, Empty, Data). It owns the MARKUP only:
 * every word stays at the call site, because the same condition is answered differently to
 * an admin, to an agency and to a teen reading her own pay, and a component that bakes in
 * wording forces those three to become one sentence or three components.
 *
 * Used by: every hub surface with something to say when a list came back empty. The hub
 * built this eight ways across ~98 sites before there was anywhere to put it.
 *
 * @gotcha it is not the failed-read state and never stands in for one. `.empty-state` makes
 *         a positive claim, and a refused read has no claim to make: that is `ReadError`.
 * @gotcha `filtered.unfiltered` is the second half of the discriminator and is not optional.
 *         `filtered.dirty` alone is wrong on any surface that opens on a period (Rewards
 *         opens on LAST month), which is dirty before the reader has touched a control.
 * @see .claude/rules/hub-ui.md (the four data states, "An empty state names what emptied
 *      it"), docs/DESIGN.md section 3, components/shared/ReadError.js
 */
import React from 'react';

/**
 * The two geometries, until `App.css` carries them as classes.
 *
 * `block` is `.empty-state` untouched: a centred 60px panel, the state of a whole SURFACE.
 * `note` is the shape 36 `.text-muted` one-liners had already settled on independently, a
 * left-aligned line for a section inside a card or a detail panel, where the block form
 * would push the next section off the screen.
 */


/** How many rows a set holds, given the array, a count, or just whether it has any. */
function sizeOf(unfiltered) {
  if (Array.isArray(unfiltered)) return unfiltered.length;
  if (typeof unfiltered === 'number') return unfiltered;
  return unfiltered ? 1 : 0;
}

/**
 * @param {object} props
 * @param {React.ReactNode} [props.icon] the glyph above the title, at 36px and 30% opacity
 * @param {React.ReactNode} [props.title] the one-line claim
 * @param {React.ReactNode} [props.text] the sentence under it
 * @param {React.ReactNode} [props.action] the control that answers the emptiness. Omit when
 *        the emptiness is the answer.
 * @param {'block'|'note'} [props.variant='block'] surface state, or a line inside a section
 * @param {React.ReactNode} [props.children] a body this shape cannot express, rendered under
 *        the text. Two surfaces need it and both are deliberate: My Money sets its title in
 *        the display face, and the tax estimate is one unbroken sentence.
 * @param {object} [props.filtered] this surface's own filters, and the copy for when THEY
 *        are what emptied it. `{ unfiltered, dirty, title, text, onClear, clearLabel }`.
 *        `unfiltered` is the set BEFORE the filters ran (the array, its length, or whether
 *        it holds anything): with nothing in it the filters hid nothing and the plain copy
 *        is the true one. `onClear` renders only when `dirty` is also true, so a page that
 *        opens on a period does not offer to clear a filter nobody set.
 * @param {object} [props.style] per-site geometry, usually padding. Not a place for colour.
 * @param {string} [props.role] only `ErrorBoundary` passes one, to announce a crash panel.
 */
export default function EmptyState({
  icon, title, text, action, children, filtered, variant = 'block', style, role,
}) {
  const filteredOut = filtered ? sizeOf(filtered.unfiltered) > 0 : false;
  const shownTitle = filteredOut && filtered.title !== undefined ? filtered.title : title;
  const shownText = filteredOut && filtered.text !== undefined ? filtered.text : text;

  // The control that undoes the filters replaces the ordinary action: an empty state offers
  // one way out, and the way out of a filter is always the filter.
  const clear = filteredOut && filtered.dirty && filtered.onClear ? (
    <button className="btn btn-ghost btn-sm" onClick={filtered.onClear}>
      {filtered.clearLabel || 'Clear filters'}
    </button>
  ) : null;
  const foot = clear || action;

  return (
    <div className={variant === 'note' ? 'empty-state empty-state-note' : 'empty-state'} role={role}
         style={style}>
      {icon ? <div className="empty-state-icon">{icon}</div> : null}
      {shownTitle ? <div className="empty-state-title">{shownTitle}</div> : null}
      {shownText ? <div className="empty-state-text">{shownText}</div> : null}
      {children}
      {foot ? <div className="empty-state-action" style={variant === 'note' ? { justifyContent: 'flex-start' } : undefined}>{foot}</div> : null}
    </div>
  );
}
